            "field": "day",
            "type": "temporal",
            "title": "Date"
          },
          {
            "field": "totalHours",
            "type": "quantitative",
            "title": "Hours"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "line",
        "color": "orange",
        "size": 2
      },
      "transform": [
        {
          "window": [
            {
              "op": "mean",
              "field": "totalHours",
              "as": "rollingMean"
            }
          ],
